static JceWorldStreamer *s_world_streamer = NULL;
/* One runtime asset view for startup scenes, streamed chunks, and loose
 * developer overrides. It mounts the embedded PAK plus an optional cooked
 * directory, with the VFS's documented loose-over-PAK precedence. */
static JceFileSystem    *s_runtime_fs     = NULL;

/* Runtime mesh cache (path → JceMesh*).
 *
 * The scene renderer calls cbs.load_mesh for every mesh-renderer entity
 * once PER render pass — shadow cascades + depth pre-pass + main pass —
 * i.e. many times per entity per frame.  jce_model_importer_load_pak
 * runs a full pipeline on every call: ZSTD-decompress the asset out of
 * the PAK, a complete Assimp import (GenSmoothNormals + CalcTangentSpace
 * + PreTransformVertices) and a fresh GPU vertex/index buffer upload.
 *
 * Without a cache the deployed exe re-imports every mesh every frame,
 * which both tanks the frame rate and leaks bgfx buffers.  The editor
 * never hits this because its load_mesh callback is backed by the editor
 * asset cache; the standalone runtime must provide its own.  Meshes are
 * owned here and destroyed in app_exit. */
/* Grows on demand — never a fixed cap.  A large streamed world can reference
 * thousands of DISTINCT meshes; an overflowing fixed cache would silently stop
 * caching the excess and re-import it every pass every frame (the exact
 * per-frame cliff this cache exists to prevent).  Lookup is O(1) via an
 * open-addressing hash index (linear probe over a power-of-two table keyed by
 * an FNV-1a hash of the path) so the per-entity-per-pass hot path never
 * linear-scans.  Failed imports are cached (mesh == NULL) so a missing asset
 * is not re-attempted every frame either. */
typedef struct {
    char    *path;   /* owned copy                     */
    JceMesh *mesh;   /* NULL == cached failed import    */
    uint64_t hash;   /* FNV-1a of path                  */
} JceDefaultMeshEntry;
static JceDefaultMeshEntry *s_mesh_cache       = NULL;  /* s_mesh_cache_count entries */
static int32_t             *s_mesh_index       = NULL;  /* slot -> entry idx, -1 empty */
static uint32_t             s_mesh_index_cap   = 0;     /* power of two, or 0 */
static uint32_t             s_mesh_cache_count = 0;
static uint32_t             s_mesh_cache_cap   = 0;

/* Case-insensitive ".gltf"/".glb" suffix test.  cgltf is the engine's single
 * glTF authority (the scene renderer routes such a mesh_path to its JceModel /
 * cgltf cache and never reaches this callback); assimp is the importer for the
 * authoring formats cgltf cannot read.  Hand-rolled rather than strcasecmp
 * because that is POSIX, not C99. */
static bool dm_path_is_gltf(const char *s) {
    size_t n = strlen(s);
    for (int k = 0; k < 2; ++k) {
        const char *suf = k ? ".gltf" : ".glb";
        size_t      sn  = k ? 5u : 4u;
        if (n < sn) continue;
        const char *p = s + (n - sn);
        size_t      i = 0;
        for (; i < sn; ++i) {
            char a = p[i];
            if (a >= 'A' && a <= 'Z') a = (char)(a - 'A' + 'a');
            if (a != suf[i]) break;
        }
        if (i == sn) return true;
    }
    return false;
}

/* FNV-1a 64-bit — small, deterministic, avoids pulling xxhash into this TU. */
static uint64_t dm_path_hash(const char *s) {
    uint64_t h = 1469598103934665603ULL;
    for (; *s; ++s) { h ^= (unsigned char)*s; h *= 1099511628211ULL; }
    return h;
}

/* Entry index for hash/path, or -1 if absent (open-addressing linear probe). */
static int dm_mesh_cache_find(uint64_t hash, const char *path) {
    if (!s_mesh_index_cap) return -1;
    uint32_t mask = s_mesh_index_cap - 1;
    for (uint32_t slot = (uint32_t)hash & mask; ; slot = (slot + 1) & mask) {
        int32_t ei = s_mesh_index[slot];
        if (ei < 0) return -1;
        if (s_mesh_cache[ei].hash == hash &&
            strcmp(s_mesh_cache[ei].path, path) == 0) return ei;
    }
}

/* Place entry `ei` into the index (caller guarantees a free slot exists). */
static void dm_mesh_index_put(int32_t ei) {
    uint32_t mask = s_mesh_index_cap - 1;
    uint32_t slot = (uint32_t)s_mesh_cache[ei].hash & mask;
    while (s_mesh_index[slot] >= 0) slot = (slot + 1) & mask;
    s_mesh_index[slot] = ei;
}

/* Keep the index under a 0.75 load factor; rebuild on growth.  Returns false
 * only on allocation failure (caller then skips caching this mesh). */
static bool dm_mesh_index_reserve(uint32_t want) {
    if (s_mesh_index_cap && want * 4u < s_mesh_index_cap * 3u) return true;
    uint32_t ncap = s_mesh_index_cap ? s_mesh_index_cap : 64u;
    while (want * 4u >= ncap * 3u) ncap *= 2u;
    int32_t *ni = (int32_t *)malloc(sizeof(int32_t) * ncap);
    if (!ni) return false;
    for (uint32_t i = 0; i < ncap; ++i) ni[i] = -1;
    free(s_mesh_index);
    s_mesh_index     = ni;
    s_mesh_index_cap = ncap;
    for (uint32_t i = 0; i < s_mesh_cache_count; ++i) dm_mesh_index_put((int32_t)i);
    return true;
}
/* s_yaw / s_pitch removed: camera owns its own yaw/pitch now and
 * we stopped using the third-person orbit math that depended on them. */

/* Mount every bundle baked into `.rdata` by CMake's embed step.
 * Memory-resident JPAKs are a borrowed view of the exe's read-only
 * segment, so the runtime never copies and the binary stays a
 * genuinely single self-contained file (no sidecar bundles/). */
static void jce_default_mount_project_bundles(void)
{
#if JCE_PROJECT_EMBEDDED_BUNDLE_COUNT > 0
    s_bundle_fs = jce_fs_create();
    if (!s_bundle_fs) {
        LOG_WARN("app", "%s", "jce_fs_create failed — bundles not mounted");
        return;
    }
    s_bundle_files = (JceBundleFile **)calloc(
        (size_t)JCE_PROJECT_EMBEDDED_BUNDLE_COUNT,
        sizeof(JceBundleFile *));
    if (!s_bundle_files) return;
    for (int i = 0; jce_project_embedded_bundles[i].name; ++i) {
        const char    *name = jce_project_embedded_bundles[i].name;
        const void    *data = jce_project_embedded_bundles[i].data;
        size_t         sz   = *jce_project_embedded_bundles[i].size;
        JceBundleFile *bf   = jce_bundle_file_open_memory(
                                  s_bundle_fs, data, sz, name);
        if (!bf) {
            LOG_WARN("app", "jce_bundle_file_open_memory failed: %s", name);
            continue;
        }
        s_bundle_files[s_bundle_count++] = bf;
        LOG_INFO("app", "bundle mounted (embed): %s (%zu bytes)", name, sz);
    }
#endif
}

static void jce_default_unmount_project_bundles(void)
{
    /* Detach overlays from the engine PAK before destroying the
     * bundle archives so a future jce_pak_find on svc->pak doesn't
     * walk into freed memory. */
    if (s_engine_pak) {
        for (int i = 0; i < s_bundle_count; ++i) {
            JcePakArchive *bp = s_bundle_files[i]
                ? (JcePakArchive *)jce_bundle_file_pak(s_bundle_files[i])
                : NULL;
            if (bp) jce_pak_overlay_remove(s_engine_pak, bp);
        }
        s_engine_pak = NULL;
    }
    for (int i = 0; i < s_bundle_count; ++i) {
        if (s_bundle_files[i]) jce_bundle_file_close(s_bundle_files[i]);
    }
    free(s_bundle_files);
    s_bundle_files = NULL;
    s_bundle_count = 0;
    if (s_bundle_fs) { jce_fs_destroy(s_bundle_fs); s_bundle_fs = NULL; }
}

static JceProject *jce_default_load_project_manifest(void)
{
    char base[1024] = {0};
    JceProject *project = NULL;

    if (jce_fs_host_get_base_path(base, sizeof(base)))
        project = jce_project_load(base);
    if (!project)
        project = jce_project_load(".");
    return project;
}

static bool jce_default_mount_runtime_assets(const JceProject *proj)
{
    bool has_pak = false;
    bool has_loose = false;
    char base[1024] = {0};

    s_runtime_fs = jce_fs_create();
    if (!s_runtime_fs) {
        LOG_ERROR("app", "%s", "could not create runtime asset filesystem");
        return false;
    }

    if (s_engine_pak) {
        has_pak = jce_fs_mount_pak(s_runtime_fs, s_engine_pak);
        if (!has_pak)
            LOG_ERROR("app", "%s", "embedded PAK could not be mounted");
    }

    if (jce_fs_host_get_base_path(base, sizeof(base))) {
        const char *cooked = (proj && proj->cooked_assets &&
                              proj->cooked_assets[0])
                             ? proj->cooked_assets : "resources/_cooked";
        char root[1200];
        int n = snprintf(root, sizeof(root), "%s%s", base, cooked);
        if (n > 0 && n < (int)sizeof(root) &&
            jce_fs_host_exists_dir(root)) {
            has_loose = jce_fs_mount_dir(s_runtime_fs, "", root);
            if (!has_loose)
                LOG_ERROR("app", "cooked asset dir could not be mounted: %s",
                          root);
        }
    }

    if (!has_pak && !has_loose) {
        LOG_ERROR("app", "%s", "no runtime asset source is available");
        jce_fs_destroy(s_runtime_fs);
        s_runtime_fs = NULL;
        return false;
    }

    /* Make the mounted runtime view visible to legacy loaders which consume
     * project-relative paths through jce_fs_host_read_all(). Without this,
     * a copied single-executable app could load the startup scene explicitly
     * from its PAK yet later CPU-side assets silently fell back to the host
     * filesystem and disappeared outside the build directory. */
    jce_fs_set_active(s_runtime_fs);

    LOG_INFO("app", "runtime assets mounted: pak=%s loose=%s",
             has_pak ? "yes" : "no", has_loose ? "yes" : "no");
    return true;
}

/* Resolve the startup scene through the unified runtime asset view.  A loose
 * project manifest is an explicit developer override; otherwise the packed
 * boot manifest determines the shipping scene. */
static bool jce_default_load_startup_scene(
    const JceProject *proj, const JceRuntimeBootManifest *boot)
{
    const char *scene_path = (proj && proj->startup_scene &&
                              proj->startup_scene[0])
                                 ? proj->startup_scene : NULL;
    if (!scene_path) {
        if (boot && boot->startup_scene[0]) {
            scene_path = boot->startup_scene;
            LOG_INFO("app", "startup scene selected from runtime boot: %s",
                     scene_path);
        }
    }
    if (!scene_path) {
        for (int i = 0; i < s_bundle_count; ++i) {
            const char *sp = jce_bundle_file_scene_path(s_bundle_files[i]);
            if (sp && sp[0]) {
                scene_path = sp;
                LOG_INFO("app", "startup_scene unset; using bundle scene: %s", sp);
                break;
            }
        }
    }
    if (!scene_path) return true; /* Intentional empty-project boot. */

    if (!s_runtime_fs) {
        LOG_ERROR("app", "%s", "startup scene requested without runtime assets");
        return false;
    }

    s_scene = jce_scene_create();
    if (!s_scene) { LOG_ERROR("app", "%s", "jce_scene_create failed"); return false; }

    if (!jce_scene_serial_load_vfs(s_scene, s_runtime_fs, scene_path)) {
        LOG_ERROR("app", "failed to load startup scene from runtime assets: %s",
                  scene_path);
        jce_scene_destroy(s_scene); s_scene = NULL;
        return false;
    }
    LOG_INFO("app", "startup scene loaded (runtime assets): %s", scene_path);
    return true;
}

/* World-streamer entity callbacks (streaming M3): wire a freshly-streamed
 * chunk's entities into the live runtime gameplay (scripts + on_start, triggers,
 * NPCs, runtime bodies) and release them again on cell unload, so gameplay lives
 * in streamed cells instead of just rendering.  `user` is the JceRuntime*.  The
 * despawn fires while the ids are still valid (BEFORE the streamer destroys the
 * scene entities), so the runtime can drop every per-entity reference first. */
static void s_default_streamer_spawn_cb(const uint64_t *ids, uint32_t count,
                                        void *user)
{
    jce_runtime_spawn_gameplay_for_ids((JceRuntime *)user, ids, count);
}

static void s_default_streamer_despawn_cb(const uint64_t *ids, uint32_t count,
                                          void *user)
{
    jce_runtime_despawn_gameplay_for_ids((JceRuntime *)user, ids, count);
}

/* VRAM ceiling: report a streamed chunk's REAL GPU footprint to the streaming
 * budget by summing its entities' resolved model VB+IB+texture bytes from the
 * scene renderer's cache (jce_scene_renderer_entities_vram_bytes).  `user` is
 * unused (the renderer + scene are file-statics).  Returns 0 before the scene
 * renderer / scene exist or while a chunk's async model decodes are still in
 * flight; the streamer then keeps its per-entity estimate and re-queries over a
 * short window so the figure converges to real bytes. */
static uint64_t s_default_streamer_residency_cb(const uint64_t *ids,
                                                uint32_t count, void *user)
{
    (void)user;
    if (!s_scene_renderer || !s_scene) return 0;
    return jce_scene_renderer_entities_vram_bytes(s_scene_renderer, s_scene,
                                                  ids, count);
}

/* Build the world streamer from the startup scene's authored streaming
 * settings. Chunks share the startup scene's unified runtime asset view,
 * preserving loose-over-PAK precedence for the complete scene. */
static void jce_default_init_world_streaming(const JceProject *proj)
{
    (void)proj;
    if (!s_scene) return;

    const JceSceneStreamingSettings *st =
        jce_scene_get_streaming_settings(s_scene);
    if (!st || !st->enabled || st->chunk_count == 0) return;

    JceFileSystem *fs = s_runtime_fs;
    if (!fs) {
        LOG_WARN("app", "%s", "world streaming: runtime assets unavailable");
        return;
    }

    JceWorldStreamConfig wsc = jce_world_stream_config_default();
    wsc.mode            = (st->mode == 1) ? JCE_STREAM_RECTANGULAR
                                          : JCE_STREAM_RADIAL;
    wsc.load_radius     = st->load_radius;
    wsc.unload_radius   = st->unload_radius;
    wsc.max_pending     = st->max_pending;
    wsc.budget_mb       = st->budget_mb;
    wsc.frame_budget_ms = st->frame_budget_ms;

    /* Streaming owns its bounded structured executor. Scene apply remains
     * time-sliced on the main thread; Web advances loads cooperatively. */
#if !JCE_PLATFORM_WEB
    wsc.single_thread = false;
#else
    wsc.single_thread = true;
#endif

    s_world_streamer = jce_world_streamer_create(&wsc, s_scene, fs, NULL);
    if (!s_world_streamer) {
        LOG_WARN("app", "%s", "world streamer creation failed — streaming disabled");
        return;
    }
    jce_world_streamer_register_from_scene_settings(s_world_streamer, st);
    /* Wire streamed-cell entities into the live runtime gameplay (streaming M3):
     * a script / trigger / NPC authored in a streamed chunk comes alive (on_start
     * / on_update, trigger observer, body) instead of only rendering, and is
     * released cleanly on cell unload.  No-op when no runtime (physics disabled). */
    if (s_runtime)
        jce_world_streamer_set_entity_callbacks(s_world_streamer,
                                                s_default_streamer_spawn_cb,
                                                s_default_streamer_despawn_cb,
                                                s_runtime);

    /* VRAM ceiling: report real per-chunk GPU residency to the budget AND arm
     * the renderer's model-cache eviction so freeing ECS entities on cell
     * unload actually frees their GPU mesh/texture.  The model cache is the
     * dominant streamed-VRAM consumer, so give it the streaming budget as its
     * ceiling (bytes).  Both no-ops when budget_mb == 0 (unlimited) or there is
     * no scene renderer. */
    if (s_scene_renderer) {
        jce_world_streamer_set_residency_query(
            s_world_streamer, s_default_streamer_residency_cb, NULL);
        if (st->budget_mb > 0)
            jce_scene_renderer_set_model_vram_budget(
                s_scene_renderer,
                (uint64_t)st->budget_mb * 1024ULL * 1024ULL);
    }
    /* HLOD far-skyline proxy swap: hide a cell's cheap always-resident proxy
     * box ("HLOD_<gx>_<gz>") once its detailed geometry streams in, show it
     * again on unload.  Shared engine impl (jce_world_streamer_attach_hlod) —
     * the SAME code the editor uses — so the standalone exe no longer
     * double-draws / z-fights the proxy over the real streamed buildings.  The
     * runtime has no extra per-chunk concern, so no chained callback. */
    jce_world_streamer_attach_hlod(s_world_streamer, s_scene, NULL, NULL);
    LOG_INFO("app", "world streaming active (%u chunks, r=%.0f/%.0f)",
             jce_world_streamer_chunk_count(s_world_streamer),
             wsc.load_radius, wsc.unload_radius);
}

/* Resolve an asset-relative path (as written in scene JSON) to an absolute
 * path jce_fs_host_read_all can open, by anchoring it under the staged cooked
 * tree (<exe_dir>/<cooked_assets>/).  The shipped exe runs with CWD == exe dir
 * (or any other dir), never the cooked-tree root, so engine-side file loads
 * that bypass the PAK (anim state machines, terrain meta/bin, HDR, etc.) would
 * otherwise be opened relative to the process CWD and fail — the same class of
 * bug the editor avoids by installing its own resolver.  Returns false (leave
 * the path as-is) for already-absolute inputs or when the anchored file does
 * not exist, so PAK-backed and embedded-bundle projects are unaffected. */
static bool s_default_resolve_path(const char *in, char *out, int outsz, void *ud)
{
    (void)ud;
    if (!in || !in[0] || !out || outsz <= 0) return false;
    /* Already absolute (drive letter, UNC, or POSIX root) → use as-is. */
    if (in[0] == '/' || in[0] == '\\' ||
        (in[0] && in[1] == ':')) return false;

    char base[1024] = {0};
    if (!jce_fs_host_get_base_path(base, sizeof(base))) return false;
    const char *cooked = (s_project && s_project->cooked_assets &&
                          s_project->cooked_assets[0])
                         ? s_project->cooked_assets : "resources/_cooked";
    int n = snprintf(out, (size_t)outsz, "%s%s/%s", base, cooked, in);
    if (n <= 0 || n >= outsz) return false;
    return jce_fs_host_exists_file(out);
}

/* JceRuntimeDesc.resolve_path_fn adapter: same cooked-tree anchoring as
 * s_default_resolve_path, with the runtime's (user_data, in, out, size)
 * argument order. */
static bool s_runtime_resolve_path(void *user_data, const char *in_path,
                                   char *out_path, int out_size)
{
    return s_default_resolve_path(in_path, out_path, out_size, user_data);
}

static JceMesh *s_default_load_mesh(const char *path, void *ud)
{
    (void)ud;
    /* Load NON-glTF geometry (.obj / .fbx / .dae / …) from the overlaid PAK
     * chain.  When a bundle is mounted (jce_pak_overlay_push), the PAK walk
     * automatically finds files inside the bundle.
     *
     * glTF is explicitly NOT handled here: cgltf owns that format end to end
     * (materials, skins, morph targets, the JCE_lod / JCE_meshlets primitive
     * extensions), and jce_model_importer_* is the assimp path, which flattens
     * to one static JceMesh and drops all of it.  The scene renderer already
     * classifies a .gltf/.glb mesh_path as a MODEL and resolves it through its
     * own cgltf cache without ever calling this callback, so the gate below is
     * an assertion of that contract rather than a behaviour change — it keeps
     * a second glTF parser out of the shipped runtime should another caller
     * (e.g. a pick pass) be wired to load_mesh later.
     *
     * Results are cached by path: the renderer calls this many times per
     * frame (once per shadow cascade / depth / main pass per entity), and
     * each import is expensive (decompress + Assimp + GPU upload). */
    if (!s_engine_pak || !path || path[0] == '\0') return NULL;
    if (dm_path_is_gltf(path)) return NULL;

    uint64_t h  = dm_path_hash(path);
    int      ei = dm_mesh_cache_find(h, path);
    if (ei >= 0) return s_mesh_cache[ei].mesh;   /* NULL == cached failure */

    JceMesh *mesh = jce_model_importer_load_pak(s_engine_pak, path);

    /* Cache the result (including a NULL failure) — grow on demand so a large
     * world never overflows the cache and re-imports the excess every frame. */
    if (s_mesh_cache_count == s_mesh_cache_cap) {
        uint32_t ncap = s_mesh_cache_cap ? s_mesh_cache_cap * 2u : 64u;
        JceDefaultMeshEntry *ne = (JceDefaultMeshEntry *)realloc(
            s_mesh_cache, sizeof(JceDefaultMeshEntry) * ncap);
        if (ne) { s_mesh_cache = ne; s_mesh_cache_cap = ncap; }
    }
    if (s_mesh_cache_count < s_mesh_cache_cap &&
        dm_mesh_index_reserve(s_mesh_cache_count + 1u)) {
        char *pc = (char *)malloc(strlen(path) + 1);
        if (pc) {
            strcpy(pc, path);
            uint32_t idx = s_mesh_cache_count++;
            s_mesh_cache[idx].path = pc;
            s_mesh_cache[idx].mesh = mesh;
            s_mesh_cache[idx].hash = h;
            dm_mesh_index_put((int32_t)idx);
        }
    }
    return mesh;
}

/* Renderer anim-event hook → runtime script dispatch (P1 anim-events).  The
 * scene renderer fires this for every authored animation frame event in the
 * (prev,cur] clip-time window; we forward it to the firing entity's gameplay
 * script (on_anim_event) through the runtime.  `user` is the JceRuntime*. */
static void s_default_anim_event_cb(uint64_t entity, const JceAnimEvent *ev,
                                    void *user)
{
    jce_runtime_dispatch_anim_event((JceRuntime *)user, entity, ev);
}

/* Renderer anim-state hook → runtime script dispatch (state-enter/exit).  The
 * scene renderer fires this once whenever a bound animation state machine's
 * active state changes; we forward it to the entity's gameplay script
 * (on_state_exit / on_state_enter) through the runtime.  `user` is the
 * JceRuntime*. */
static void s_default_anim_state_cb(uint64_t entity, const char *from_state,
                                    const char *to_state, void *user)
{
    jce_runtime_dispatch_anim_state((JceRuntime *)user, entity,
                                    from_state, to_state);
}

/* Renderer ground-query hook → runtime physics raycast (Foot IK).  The scene
 * renderer calls this per foot to find the ground under the ankle. */
static bool s_default_ground_query_cb(uint64_t entity, const float origin[3],
                                      const float dir[3], float max_dist,
                                      float *out_hit_y, float out_normal[3],
                                      void *user)
{
    (void)entity;
    return jce_runtime_ground_raycast((JceRuntime *)user, origin, dir, max_dist,
                                      out_hit_y, out_normal);
}

/* Single-exe fallback for the host-fs-anchored cooked config loaders
 * (physics_layers.json / render_settings.json): decompress a small cooked
 * config file straight out of the embedded PAK into a heap buffer.  Returns
 * malloc'd bytes (caller frees) + *out_len, or NULL on miss / oversize.  This
 * mirrors the render-pipeline PAK fallback (jce_render_pipeline_load_pak) so a
 * true single self-contained exe (no loose cooked tree) still applies its
 * authored settings instead of silently reverting to engine defaults. */
static char *dm_pak_read_config(const char *pak_key, size_t *out_len)
{
    if (!s_engine_pak || !pak_key || !pak_key[0] || !out_len) return NULL;
    const JcePakAsset *a = jce_pak_find(s_engine_pak, pak_key);
    if (!a || a->original_size == 0 || a->original_size > (1u << 20)) return NULL;
    char *buf = (char *)malloc((size_t)a->original_size);
    if (!buf) return NULL;
    if (jce_pak_decompress(a, buf, (size_t)a->original_size) !=
        (size_t)a->original_size) { free(buf); return NULL; }
    *out_len = (size_t)a->original_size;
    return buf;
}

static bool app_init(const JceServices *svc, void *ud)
{
    (void)ud;
    s_svc = svc;

    memset(&s_kpi_game_shots, 0, sizeof(s_kpi_game_shots));
    s_kpi_game_shots_active = false;
    {
        const char *spec = getenv("JCE_KPI_GAME_SHOTS");
        if (spec && spec[0]) {
            char error[192];
            if (jce_screenshot_schedule_parse(
                    spec, &s_kpi_game_shots, error, sizeof(error))) {
                s_kpi_game_shots_active = true;
                LOG_INFO("app", "deterministic game capture enabled (%d shot%s)",
                         s_kpi_game_shots.count,
                         s_kpi_game_shots.count == 1 ? "" : "s");
            } else {
                LOG_ERROR("app", "invalid JCE_KPI_GAME_SHOTS: %s", error);
            }
        }
    }

    /* Media dir for the F12/F9 presets = the exe's directory (screenshots/
     * and recordings/ are created lazily on first use). */
    if (!jce_fs_host_get_base_path(s_preset_media_dir,
                                   sizeof s_preset_media_dir))
        s_preset_media_dir[0] = '\0';

    jce_default_mount_project_bundles();

    /* Promote bundle[0] as base render PAK when project ships no
     * cooked tree (jbundle-only projects).  Otherwise overlay all
     * bundles behind svc->pak so engine subsystems see one merged
     * archive. */
    s_engine_pak = svc ? (JcePakArchive *)svc->pak : NULL;
    if (s_engine_pak) {
        for (int i = 0; i < s_bundle_count; ++i) {
            JcePakArchive *bp =
                (JcePakArchive *)jce_bundle_file_pak(s_bundle_files[i]);
            if (bp) jce_pak_overlay_push(s_engine_pak, bp);
        }
    } else if (s_bundle_count > 0) {
        s_engine_pak =
            (JcePakArchive *)jce_bundle_file_pak(s_bundle_files[0]);
        for (int i = 1; i < s_bundle_count; ++i) {
            JcePakArchive *bp =
                (JcePakArchive *)jce_bundle_file_pak(s_bundle_files[i]);
            if (bp && s_engine_pak)
                jce_pak_overlay_push(s_engine_pak, bp);
        }
        if (s_engine_pak)
            LOG_INFO("app", "no engine PAK — promoted bundle '%s' as render PAK",
                     jce_bundle_file_id(s_bundle_files[0]));
    }

    /* Settings S2: the engine-init boot ran BEFORE any game PAK was mounted,
     * so a packaged single-exe game always fell back to the tier preset and
     * silently lost its authored render-pipeline asset.  Re-resolve now that
     * bundles are overlaid: host file (CWD, exe dir) first, then the packed
     * key.  Strict no-op when nothing resolves. */
    jce_render_pipeline_apply_boot_mounted(
        (const struct JcePakArchive *)s_engine_pak,
        "Settings/RenderPipeline.rp.json",
        "settings/render_pipeline.rp.json");

    /* Settings S7 follow-up: re-layer the player's saved in-game graphics
     * choices (jce.ini [graphics]) — the re-resolve above may have replaced
     * the pipeline with the packed .rp.json, and the player's own choices
     * (layer 4, USER CONFIG) outrank the asset (layer 3).  Strict no-op when
     * the config carries no [graphics] section. */
    if (svc)
        jce_engine_apply_graphics_config(svc->config, svc->renderer);

    s_project = jce_default_load_project_manifest();
    JceRuntimeBootManifest runtime_boot = {0};
    const bool boot_entry_present = s_engine_pak &&
        jce_pak_find(s_engine_pak, JCE_RUNTIME_BOOT_MANIFEST_PATH);
    const bool boot_loaded = s_engine_pak &&
        jce_runtime_boot_manifest_load_pak(s_engine_pak, &runtime_boot);
    if (boot_entry_present && !boot_loaded) {
        LOG_ERROR("app", "%s", "runtime boot manifest is invalid");
        return false;
    }
    if (!s_project && !boot_loaded) {
        LOG_ERROR("app", "%s",
                  "jce_project.json and packed runtime boot manifest are both missing");
        return false;
    }
    /* Player window metadata (Project Settings > Player, boot manifest schema
     * >= 2): open the shipped game with the authored window title + fullscreen.
     * The manifest loads AFTER window creation, so only title (no visible flash)
     * and fullscreen are applied here; the authored window SIZE has no
     * post-create setter yet and keeps the engine-config default. */
    if (boot_loaded && svc && svc->window) {
        if (runtime_boot.window_title[0])
            jce_window_set_title(svc->window, runtime_boot.window_title);
        if (runtime_boot.fullscreen && !jce_window_is_fullscreen(svc->window))
            jce_window_toggle_fullscreen(svc->window);
    }
    if (!jce_default_mount_runtime_assets(s_project))
        return false;
    if (!jce_default_load_startup_scene(s_project,
                                        boot_loaded ? &runtime_boot : NULL)) {
        return false;
    }

    /* Anchor component-relative *.particles.json reads under the staged
     * cooked tree (same class of fix as s_default_resolve_path below: those
     * reads are otherwise CWD-relative and fail when CWD != cooked root). */
    {
        char base[1024] = {0};
        if (jce_fs_host_get_base_path(base, sizeof(base))) {
            const char *cooked = (s_project && s_project->cooked_assets &&
                                  s_project->cooked_assets[0])
                                 ? s_project->cooked_assets : "resources/_cooked";
            char root[1200];
            snprintf(root, sizeof root, "%s%s", base, cooked);
            jce_scene_particles_set_asset_root(root);
        }
    }
    /* Single-exe: publish the overlaid game PAK so *.particles.json descriptors
     * load straight from the embedded PAK when no loose cooked tree ships beside
     * the exe (the host-fs anchor above then just serves loose dev builds). */
    jce_scene_particles_set_pak((const struct JcePakArchive *)s_engine_pak);

    JceCameraDesc cam_desc = {0};
    cam_desc.mode       = JCE_CAMERA_PERSPECTIVE;
    cam_desc.position   = jce_v3(0.0f, 2.0f, 5.0f);
    cam_desc.target     = jce_v3(0.0f, 0.5f, 0.0f);
    cam_desc.up         = jce_v3(0.0f, 1.0f, 0.0f);
    cam_desc.fov_deg    = 60.0f;
    cam_desc.near_plane = 0.1f;
    cam_desc.far_plane  = 1000.0f;
    s_camera = jce_camera_create(&cam_desc);

    if (svc && svc->renderer) {
        JceSceneRendererCallbacks cbs = {0};
        cbs.load_mesh    = s_default_load_mesh;
        /* Anchor engine-side relative file loads (anim state machines, terrain
         * meta/bin, HDR, ...) under the staged cooked tree so they resolve in a
         * shipped exe whose CWD is not the cooked-tree root.  Mirrors the
         * editor's own resolver; harmless for PAK/bundle-only projects (returns
         * false → path used as-is). */
        cbs.resolve_path = s_default_resolve_path;
        s_scene_renderer = jce_scene_renderer_create(
                               svc->renderer, s_engine_pak, &cbs);
        /* A shipped game is always "playing": enable the animation
         * state-machine / auto-locomotion driver that the editor only
         * turns on during Play (otherwise authored .anim_sm.json bindings
         * and auto_speed stay inert in deployed exes). */
        if (s_scene_renderer)
            jce_scene_renderer_set_anim_sm_active(s_scene_renderer, true);
    }
    if (!s_scene_renderer)
        LOG_WARN("app", "%s", "jce_scene_renderer_create failed — scene will not render");

    /* Occlusion culler (M5): activate GPU-query two-pass coherence culling in
     * the shipped runtime, mirroring the editor scene-view.  Only the engine's
     * embedded 'color' program is needed for the depth-only proxy draws, so this
     * works in a shipped exe (engine shaders are embedded; see JCE_EMBED_ENGINE
     * _SHADERS).  Opt-OUT via JCE_DISABLE_OCCLUSION=1 (A/B + safety hatch, mirrors
     * JCE_DISABLE_WCACHE).  Uses the default proxy view (254); the runtime has a
     * single scene-render path per frame so no second culler shares the view. */
    if (svc && svc->renderer) {
        /* OPT-IN now (JCE_ENABLE_OCCLUSION=1), matching the editor viewports --
         * see jce_editor_viewport_common.h for the measurements. The comment
         * below already conceded that this is a net loss on small scenes; the
         * numbers say it is also a net loss on large ones, because the query
         * budget (256 at runtime) decides nothing about 99%+ of a big scene
         * while every tracked entity still pays a proxy draw and a table scan.
         * Turning it off draws strictly MORE, so nothing can go missing. */
        const char *en = getenv("JCE_ENABLE_OCCLUSION");
        const bool dis_off = !(en && en[0] && en[0] != '0');
        /* GPU-query occlusion is a NET LOSS on small scenes: its multi-frame
         * result latency (bgfx keeps several frames in flight) exceeds any
         * hysteresis window, so entities flicker under camera rotation, and a
         * ~hundred-entity diorama occludes nothing anyway.  Skip it below a
         * threshold; large streamed worlds still get it. */
        uint32_t ent_count = 0;
        if (s_scene) jce_scene_each_entity(s_scene, dm_count_entities_cb, &ent_count);
        if (dis_off) {
            LOG_INFO("app", "%s",
                     "runtime occlusion culling OFF (opt in with "
                     "JCE_ENABLE_OCCLUSION=1)");
        } else if (ent_count > 0 && ent_count < 512) {
            LOG_INFO("app", "scene has %u entities (<512) — runtime occlusion "
                            "culling OFF (no benefit; avoids query-latency flicker)",
                     ent_count);
        } else {
            JceShaderSet oc_shaders;
            memset(&oc_shaders, 0, sizeof(oc_shaders));
            JceShaderHandle ch = jce_renderer_get_program_color(svc->renderer);
            oc_shaders.color.idx = ch.idx;
            JceOcclusionConfig oc_cfg = jce_occlusion_config_default();
            s_occlusion_culler = jce_occlusion_culler_create(&oc_cfg, &oc_shaders);
            if (!s_occlusion_culler)
                LOG_WARN("app", "%s",
                         "occlusion culler creation failed (runtime culling disabled)");
        }
    }

    /* ECS-UI (Canvas/UIImage/UIText/UIButton) overlay renderer.  Authored UI
     * components in the scene render in the deployed game exactly as they
     * preview in the editor game-view. */
    if (svc && svc->renderer) {
        s_ui_canvas = jce_ui_canvas_create(svc->renderer, s_engine_pak);
        if (!s_ui_canvas)
            LOG_WARN("app", "%s", "jce_ui_canvas_create failed — ECS-UI will not render");
    }

    /* Physics layer collision matrix (Top 4 — last-mile parity with editor
     * Play): load the project's authored matrix BEFORE jce_runtime_create so
     * bodies spawn with the correct (group,mask) collision filter, exactly like
     * the editor pushes it before its own runtime create.  The build exports it
     * into the cooked tree as `physics_layers.json` (jce.physlayers.v1); absent
     * ⇒ engine default (all layers collide).  Loose cooked tree first (a dev
     * build can hot-tweak it), then the embedded PAK — so a single
     * self-contained exe (no loose tree) still spawns with the authored
     * collision filter instead of the all-collide default. */
    {
        bool matrix_loaded = false;
        char base[1024] = {0};
        if (jce_fs_host_get_base_path(base, sizeof(base))) {
            const char *cooked = (s_project && s_project->cooked_assets &&
                                  s_project->cooked_assets[0])
                                 ? s_project->cooked_assets : "resources/_cooked";
            char lpath[1024];
            int n = snprintf(lpath, sizeof(lpath), "%s%s/physics_layers.json",
                             base, cooked);
            if (n > 0 && n < (int)sizeof(lpath) &&
                jce_physics_layer_matrix_load_json(lpath)) {
                LOG_INFO("app", "physics layer matrix loaded: %s", lpath);
                matrix_loaded = true;
            }
        }
        if (!matrix_loaded) {
            size_t clen = 0;
            char *cbuf = dm_pak_read_config("physics_layers.json", &clen);
            if (cbuf) {
                if (jce_physics_layer_matrix_load_json_mem(cbuf, clen))
                    LOG_INFO("app", "%s",
                             "physics layer matrix loaded: pak:physics_layers.json");
                free(cbuf);
            }
        }
    }

    /* Project-wide quality settings (Top 5): load the build-exported
     * render_settings.json from the cooked tree.  lod_bias applies globally
     * now; the shadow tier folds into the scene render config each frame via
     * s_default_scene_cfg().  Missing file ⇒ engine defaults. */
    {
        /* Loose cooked tree first (dev hot-tweak), then the embedded PAK, so a
         * single self-contained exe still applies the authored shadow tier /
         * MSAA / vsync / LOD bias / grass toggle instead of engine defaults. */
        bool rs_loaded = false;
        char base[1024] = {0};
        if (jce_fs_host_get_base_path(base, sizeof(base))) {
            const char *cooked = (s_project && s_project->cooked_assets &&
                                  s_project->cooked_assets[0])
                                 ? s_project->cooked_assets : "resources/_cooked";
            char rpath[1024];
            int n = snprintf(rpath, sizeof(rpath), "%s%s/render_settings.json",
                             base, cooked);
            if (n > 0 && n < (int)sizeof(rpath) &&
                jce_render_settings_load_json(rpath, &s_render_settings)) {
                LOG_INFO("app", "render settings loaded: %s", rpath);
                rs_loaded = true;
            }
        }
        if (!rs_loaded) {
            size_t clen = 0;
            char *cbuf = dm_pak_read_config("render_settings.json", &clen);
            if (cbuf) {
                if (jce_render_settings_load_json_mem(cbuf, clen, &s_render_settings)) {
                    LOG_INFO("app", "%s",
                             "render settings loaded: pak:render_settings.json");
                    rs_loaded = true;
                }
                free(cbuf);
            }
        }
        if (rs_loaded) {
            s_render_settings_loaded = true;
            jce_texture_set_global_mip_bias((int8_t)s_render_settings.lod_bias);
            /* Window-period graphics: vsync + MSAA are swapchain reset flags,
             * applied here via a GPU reset (the renderer is already created).
             * HDR is handled by the pipeline's internal HDR offscreen target +
             * tonemap, not a backbuffer flag. */
            if (svc && svc->renderer) {
                jce_renderer_set_vsync(svc->renderer, s_render_settings.vsync != 0);
                jce_renderer_set_msaa(svc->renderer, s_render_settings.msaa);
            }
            /* Grass rendering project gate (Stage 1b.6). */
            if (s_scene_renderer)
                jce_scene_renderer_set_grass_enabled(s_scene_renderer,
                    s_render_settings.grass_enabled != 0);
            LOG_INFO("app", "render settings applied (vsync=%d msaa=%d)",
                     s_render_settings.vsync, s_render_settings.msaa);
        }
    }

    if (s_scene) {
        JceRuntimeDesc rd = (JceRuntimeDesc){0};
        rd.scene          = s_scene;
        rd.pak            = s_engine_pak;
        rd.audio          = svc ? svc->audio : NULL;
        rd.enable_physics = true;
        /* Anchor runtime host-fs reads (scripts, BT trees, .seq, terrain
         * meta) to the cooked tree, mirroring the renderer's resolver.
         * Without this the runtime's host-first read resolves relative to
         * the process CWD, silently misses the loose cooked tree and falls
         * through to the PAK — loose-tree script edits beside a shipped exe
         * never load (PAK-only), unlike every other asset class. */
        rd.resolve_path_fn = s_runtime_resolve_path;

        /* Game L10n: prefer the on-disk cooked tree's i18n dir
         * (<exe_dir>/<cooked_assets>/i18n) so shipped games hot-load
         * locale edits; bundle-embedded exes fall through to rd.pak's
         * "i18n/<locale>.json" source inside jce_runtime_create.  The
         * initial locale comes from jce.ini ([app] locale=zh_cn) when
         * set; otherwise the runtime auto-detects from the OS. */
        static char s_loc_dir[1024];
        {
            char base[1024] = {0};
            if (jce_fs_host_get_base_path(base, sizeof(base))) {
                const char *cooked =
                    (s_project && s_project->cooked_assets &&
                     s_project->cooked_assets[0])
                    ? s_project->cooked_assets : "resources/_cooked";
                int n = snprintf(s_loc_dir, sizeof(s_loc_dir),
                                 "%s%s/i18n", base, cooked);
                if (n > 0 && n < (int)sizeof(s_loc_dir) &&
                    jce_fs_host_exists_dir(s_loc_dir))
                    rd.locales_dir = s_loc_dir;
            }
        }
        rd.locale = (svc && svc->config && svc->config->locale[0])
                    ? svc->config->locale : NULL;

        /* Authored audio-mixer routing (Settings/audio_mixer.json, beside
         * Settings/RenderPipeline.rp.json).  Host-first like the render
         * pipeline: CWD (dev run from the project root), then the exe dir
         * (shipped layout).  Absent => rt_init_mixer seeds the default
         * Music/SFX/Voice/UI tree.  Static: the runtime keeps the pointer. */
        static char s_mixer_cfg_path[1200];
        {
            const char *rel = "Settings/audio_mixer.json";
            char base[1024] = {0};
            if (jce_fs_host_exists_file(rel)) {
                snprintf(s_mixer_cfg_path, sizeof(s_mixer_cfg_path), "%s", rel);
                rd.mixer_config_path = s_mixer_cfg_path;
            } else if (jce_fs_host_get_base_path(base, sizeof(base))) {
                int n = snprintf(s_mixer_cfg_path, sizeof(s_mixer_cfg_path),
                                 "%s%s", base, rel);
                if (n > 0 && n < (int)sizeof(s_mixer_cfg_path) &&
                    jce_fs_host_exists_file(s_mixer_cfg_path))
                    rd.mixer_config_path = s_mixer_cfg_path;
            }
            if (rd.mixer_config_path)
                LOG_INFO("app", "audio mixer config: %s", rd.mixer_config_path);
        }

        s_runtime = jce_runtime_create(&rd);
        if (!s_runtime)
            LOG_WARN("app", "%s", "jce_runtime_create failed — physics/audio inactive");

        /* Route animation frame events into the gameplay script VM: the scene
         * renderer (which advances the event tracks) now forwards each fired
         * event to the firing entity's on_anim_event script handler via the
         * runtime.  Both handles exist here; harmless if either is NULL. */
        if (s_scene_renderer && s_runtime)
            jce_scene_renderer_set_anim_event_fn(s_scene_renderer,
                                                 s_default_anim_event_cb,
                                                 s_runtime);
        /* Route animation state-machine state changes into the script VM so
         * authored on_state_enter / on_state_exit handlers fire (mirrors the
         * frame-event wiring above). */
        if (s_scene_renderer && s_runtime)
            jce_scene_renderer_set_anim_state_fn(s_scene_renderer,
                                                 s_default_anim_state_cb,
                                                 s_runtime);
        /* Foot IK: install the renderer's ground-query hook to the runtime's
         * physics raycast so authored FootIk components adapt feet to terrain. */
        if (s_scene_renderer && s_runtime)
            jce_scene_renderer_set_ground_query_fn(s_scene_renderer,
                                                   s_default_ground_query_cb,
                                                   s_runtime);
    }

    /* Open-world streaming (no-op unless the scene's streaming settings
     * are enabled and carry registered chunks). */
    jce_default_init_world_streaming(s_project);

    /* Scene-driven boot cursor mode: capture (FPS-look) only when the scene
     * actually has a player character to drive.  Diorama / orbit / UI-first
     * scenes start with a FREE cursor so drag-orbit and authored HUD buttons
     * work immediately (Tab still toggles either way). */
    {
        bool has_character = false;
        if (s_scene) {
            JceEntity out[1];
            /* Cheap presence probe: any entity with a CharacterController. */
            has_character = dm_scene_has_any_character(s_scene, out);
        }
        s_cursor_captured = has_character;
        if (svc && svc->window) {
            jce_window_set_relative_mouse_mode(svc->window, s_cursor_captured);
            jce_window_set_mouse_grab        (svc->window, s_cursor_captured);
        }
        LOG_INFO("app", "boot cursor: %s (scene %s a CharacterController)",
                 s_cursor_captured ? "captured (FPS-look)" : "free (orbit/UI)",
                 has_character ? "has" : "has no");
    }
    return true;
}

/* Editor-authored action map drives movement when the action exists;
 * the raw scancode is the fallback so a missing/renamed action never
 * strands the player. The engine already loads input_actions.json and
 * updates the map every frame (QW-input-actions) — this is the consumer
 * side that was historically missing. */
static bool dm_act_down(const JceInput *in, const JceInputActions *acts,
                        const char *name, int fallback_key)
{
    if (acts) {
        int id = jce_action_find(acts, name);
        if (id >= 0) return jce_action_down(acts, id);
    }
    return jce_input_key_down(in, fallback_key);
}

static void app_update(float dt, void *ud)
{
    (void)ud;
    s_last_dt = dt;
    if (s_kpi_game_shots_active)
        jce_screenshot_schedule_tick(
            &s_kpi_game_shots, JCE_SCREENSHOT_CLOCK_PLAYING, (double)dt);
    if (!s_svc || !s_svc->input) return;
    const JceInput *in = s_svc->input;
    const JceInputActions *acts = s_svc->actions;

    /* Tab toggles FPS-look cursor capture.  Uncaptured ⇒ a free OS cursor the
     * player can click in-game UI with (FEATURE 4.1); captured ⇒ classic
     * mouse-look.  Apply the window mode change on the edge only. */
    if (jce_input_key_pressed(in, JCE_KEY_TAB)) {
        s_cursor_captured = !s_cursor_captured;
        if (s_svc->window) {
            jce_window_set_relative_mouse_mode(s_svc->window, s_cursor_captured);
            jce_window_set_mouse_grab        (s_svc->window, s_cursor_captured);
        }
    }

    /* ── Runtime UX presets (every default_main app) ────────────────── */

    /* Hold ALT: temporarily release the captured cursor (inspect / reach
     * in-game UI); releasing ALT restores the game's capture state. */
    {
        bool alt = jce_input_key_down(in, JCE_KEY_LALT) ||
                   jce_input_key_down(in, JCE_KEY_RALT);
        if (alt && !s_preset_alt_active) {
            s_preset_alt_active    = true;
            s_preset_alt_saved_cap = s_cursor_captured;
            if (s_cursor_captured && s_svc->window) {
                jce_window_set_relative_mouse_mode(s_svc->window, false);
                jce_window_set_mouse_grab        (s_svc->window, false);
            }
        } else if (!alt && s_preset_alt_active) {
            s_preset_alt_active = false;
            if (s_preset_alt_saved_cap && s_cursor_captured && s_svc->window) {
                jce_window_set_relative_mouse_mode(s_svc->window, true);
                jce_window_set_mouse_grab        (s_svc->window, true);
            }
        }
    }

    /* Hold ESC 2s: clean quit (same path as the window close button). */
    if (jce_input_key_down(in, JCE_KEY_ESCAPE)) {
        s_preset_esc_hold += dt;
        if (s_preset_esc_hold >= 2.0f) {
            LOG_INFO("app", "%s", "ESC held 2s — quitting");
            jce_engine_request_quit();
        }
    } else {
        s_preset_esc_hold = 0.0f;
    }

    /* F11: fullscreen toggle. */
    if (jce_input_key_pressed(in, JCE_KEY_F11) && s_svc->window)
        jce_window_toggle_fullscreen(s_svc->window);

    /* F12: screenshot -> <exe_dir>/screenshots/shot_<unix>.png. */
    if (jce_input_key_pressed(in, JCE_KEY_F12)) {
        char dir[640], path[720];
        snprintf(dir, sizeof dir, "%sscreenshots", s_preset_media_dir);
        jce_fs_host_create_directory(dir);
        snprintf(path, sizeof path, "%s/shot_%lld.png",
                 dir, (long long)time(NULL));
        if (jce_renderer_request_screenshot(path))
            LOG_INFO("app", "screenshot -> %s", path);
    }

    /* F9: toggle WebM recording -> <exe_dir>/recordings/rec_<unix>.webm.
     * Frames arrive via the renderer's backbuffer capture (interactive
     * present); encoding is synchronous VP9-realtime — fine at 720-1080p. */
    if (jce_input_key_pressed(in, JCE_KEY_F9) && s_svc->renderer) {
        if (!s_preset_rec_active) {
            s_preset_rec_active = true;
            s_preset_rec_time   = 0.0;
            s_preset_rec_w      = 0;
            jce_renderer_set_capture_sink(preset_rec_begin, preset_rec_frame,
                                          preset_rec_end, NULL);
            jce_renderer_set_backbuffer_capture(s_svc->renderer, true);
        } else {
            jce_renderer_set_backbuffer_capture(s_svc->renderer, false);
            jce_renderer_set_capture_sink(NULL, NULL, NULL, NULL);
            if (s_preset_rec) {
                jce_webm_encoder_finish(s_preset_rec);
                s_preset_rec = NULL;
                LOG_SUCCESS("app", "%s", "recording stopped");
            }
            s_preset_rec_active = false;
        }
    }
    if (s_preset_rec_active) s_preset_rec_time += (double)dt;

    /* Movement is camera-relative (W = into-the-screen) just like the
     * editor's Play view, so look direction defines move direction.
     * Only a unit DIRECTION plus button state is pushed — speeds and the
     * jump arc come from the scene's CharacterController component, so
     * the deployed exe and the editor share the same authored feel. */
    if (s_runtime) {
        JceRuntimeInput ri = (JceRuntimeInput){0};

        float fx = 0.0f, fz = 0.0f, rx = 0.0f, rz = 0.0f;
        if (s_camera) {
            jce_vec3 fwd   = jce_camera_get_forward(s_camera);
            jce_vec3 right = jce_camera_get_right  (s_camera);
            fwd.y = 0.0f; right.y = 0.0f;
            float fl = sqrtf(fwd.x*fwd.x   + fwd.z*fwd.z);
            float rl = sqrtf(right.x*right.x + right.z*right.z);
            if (fl > 0.0001f) { fx = fwd.x/fl;   fz = fwd.z/fl;   }
            if (rl > 0.0001f) { rx = right.x/rl; rz = right.z/rl; }
        }
        float wx = 0.0f, wz = 0.0f;
        if (dm_act_down(in, acts, "move_forward", JCE_KEY_W)) { wx += fx; wz += fz; }
        if (dm_act_down(in, acts, "move_back",    JCE_KEY_S)) { wx -= fx; wz -= fz; }
        if (dm_act_down(in, acts, "move_right",   JCE_KEY_D)) { wx += rx; wz += rz; }
        if (dm_act_down(in, acts, "move_left",    JCE_KEY_A)) { wx -= rx; wz -= rz; }
        float wlen = sqrtf(wx*wx + wz*wz);
        if (wlen > 0.0001f) { wx /= wlen; wz /= wlen; }
        ri.walk_x = wx;
        ri.walk_z = wz;

        bool jump_now = dm_act_down(in, acts, "jump", JCE_KEY_SPACE);
        ri.jump_pressed = jump_now && !s_jump_edge;
        ri.jump_held    = jump_now;
        s_jump_edge     = jump_now;
        ri.speed_mult   = 1.0f;
        ri.sprint = dm_act_down(in, acts, "sprint", JCE_KEY_LSHIFT) ||
                    jce_input_key_down(in, JCE_KEY_RSHIFT);
        ri.attack_pressed = dm_act_down(in, acts, "attack", JCE_KEY_J);
        if (jce_input_key_down(in, JCE_KEY_LCTRL)  ||
            jce_input_key_down(in, JCE_KEY_RCTRL))  ri.speed_mult = 0.25f;

        /* Raw pointer gameplay is runtime-owned too.  Diorama/orbit projects
         * consume this through scene scripts, while FPS projects can ignore it
         * and keep using the default camera path below. */
        jce_input_mouse_delta(in, &ri.pointer_dx, &ri.pointer_dy);
        ri.pointer_wheel = jce_input_mouse_wheel(in);
        for (int button = 1; button <= 5; ++button) {
            if (jce_input_mouse_button(in, button))
                ri.pointer_buttons |= UINT32_C(1) << (button - 1);
        }
        jce_runtime_set_input(s_runtime, &ri);
        {
            JceRuntimeTouch touches[JCE_RUNTIME_MAX_TOUCHES];
            int touch_count = jce_input_touch_count(in);
            int kept = 0;
            if (touch_count > JCE_RUNTIME_MAX_TOUCHES)
                touch_count = JCE_RUNTIME_MAX_TOUCHES;
            for (int i = 0; i < touch_count; ++i) {
                JceFingerID id = 0;
                float x = 0.0f, y = 0.0f, pressure = 0.0f;
                if (!jce_input_touch_get(in, i, &id, &x, &y, &pressure))
                    continue;
                touches[kept].id = (uint64_t)id;
                touches[kept].x = x;
                touches[kept].y = y;
                touches[kept].pressure = pressure;
                ++kept;
            }
            jce_runtime_set_touch_input(s_runtime, touches, kept);
        }
        /* Bind the live action map so gameplay scripts can read authored verbs
         * and axes by name (jce.is_action_down / get_axis), beyond the fixed
         * walk/jump/sprint/attack fields above. */
        jce_runtime_set_actions(s_runtime, acts);
        jce_runtime_step(s_runtime, dt);

        /* Scene transitions clear + reload the SAME ECS world, so recycled
         * entity ids come back with bumped generation bits and every
         * entity-keyed renderer cache slot (foliage/grass/water/canopies)
         * goes stale.  Drop them once per completed transition — content
         * rebuilds lazily on the next draw. */
        static bool s_was_transitioning = false;
        bool transitioning = jce_runtime_is_transitioning(s_runtime);
        if (s_was_transitioning && !transitioning && s_scene_renderer)
            jce_scene_renderer_reset_entity_caches(s_scene_renderer);
        s_was_transitioning = transitioning;
    }

    /* Drive chunk streaming from the live camera position (cooperative
     * mode: pending loads/applies run inside this call, on this thread). */
    if (s_world_streamer && s_camera)
        jce_world_streamer_update(s_world_streamer,
                                  jce_camera_get_position(s_camera));

    if (!s_camera) return;

    /* Cinemachine-style VCam override — parity with the editor game view
     * (jce_panel_game_view.cpp does the same in Play mode): when the scene
     * has any active VirtualCamera, its damped blended pose drives the live
     * camera and wins over both mouse-look and the player-follow / free-fly
     * logic below for this frame.  When no VCam is active, `vout` is left
     * untouched and we fall through to the FPS controls. */
    if (s_scene) {
        JceVcamOutput vout;
        bool has_vcam = false;
        jce_vcam_system_evaluate(s_scene, dt, &vout, &has_vcam);
        if (has_vcam) {
            jce_camera_set_position(s_camera,
                jce_v3(vout.position[0], vout.position[1], vout.position[2]));
            jce_camera_look_at(s_camera,
                jce_v3(vout.target[0], vout.target[1], vout.target[2]));
            jce_camera_set_fov(s_camera, vout.fov_deg);
            return;
        }
    }

    /* FPS look while the cursor is captured: cursor is grabbed so delta is
     * pure mouse motion.  Mirror editor panel_game_view convention:
     *  - +dx → look right
     *  - -dy → look up (mouse-up = look-up; standard non-inverted)
     * While uncaptured (Tab) the mouse is a free UI cursor and must not
     * steer the camera. */
    if (s_cursor_captured) {
        float dx = 0.0f, dy = 0.0f;
        jce_input_mouse_delta(in, &dx, &dy);
        if (dx != 0.0f || dy != 0.0f) {
            const float sens = 0.0025f;
            jce_camera_rotate(s_camera, dx * sens, -dy * sens);
        }
    }

    /* Detach-cam toggle (default_main only): F flips first-person player-follow
     * <-> free-fly.  Editor viewports have their own cameras and are unaffected.
     * Manual rising-edge guard (down && !prev) — no key_pressed helper assumed.
     * JCE_KEY_F == 9 (jce_keys.h:29). */
    static bool s_free_cam      = false;
    static bool s_free_cam_prev = false;
    bool f_now = jce_input_key_down(in, JCE_KEY_F);
    if (f_now && !s_free_cam_prev) s_free_cam = !s_free_cam;
    s_free_cam_prev = f_now;

    jce_vec3 player_pos;
    if (!s_free_cam && s_runtime && jce_runtime_get_player_position(s_runtime, &player_pos)) {
        /* Third-person follow: orbit the camera behind+above the player and
         * look past them, so the playable character stays visible (showcase /
         * Genshin-style).  Mouse yaw orbits the rig; F toggles to free-fly.
         * Shared with the editor Game View (jce_camera_third_person_follow) so
         * editor-Play and the runtime frame the scene identically (WYSIWYG). */
        jce_camera_third_person_follow(s_camera, player_pos);
    } else {
        float speed = 20.0f;
        if (jce_input_key_down(in, JCE_KEY_LSHIFT) ||
            jce_input_key_down(in, JCE_KEY_RSHIFT)) speed *= 3.0f;
        if (jce_input_key_down(in, JCE_KEY_LCTRL)  ||
            jce_input_key_down(in, JCE_KEY_RCTRL))  speed *= 0.25f;
        float step = speed * dt;
        if (jce_input_key_down(in, JCE_KEY_W)) jce_camera_move_forward(s_camera,  step);
        if (jce_input_key_down(in, JCE_KEY_S)) jce_camera_move_forward(s_camera, -step);
        if (jce_input_key_down(in, JCE_KEY_D)) jce_camera_move_right  (s_camera,  step);
        if (jce_input_key_down(in, JCE_KEY_A)) jce_camera_move_right  (s_camera, -step);
        if (jce_input_key_down(in, JCE_KEY_E) ||
            jce_input_key_down(in, JCE_KEY_SPACE)) jce_camera_move_up(s_camera,  step);
        if (jce_input_key_down(in, JCE_KEY_Q)) jce_camera_move_up     (s_camera, -step);
    }

}

/* Build the scene render config from defaults, folding in the project-wide
 * quality settings (Top 5) as the DEFAULT.  Per-scene JceSceneRenderingSettings
 * still override these inside jce_scene_renderer_render. */
static JceSceneRenderConfig s_default_scene_cfg(void)
{
    JceSceneRenderConfig c = jce_scene_render_config_default();
    if (s_render_settings_loaded) {
        if (s_render_settings.shadow_quality <= 0)    c.draw_shadows    = false;
        if (s_render_settings.shadow_map_size > 0)    c.shadow_map_size = (uint16_t)s_render_settings.shadow_map_size;
        if (s_render_settings.shadow_cascades > 0)    c.csm_cascades    = (uint8_t)s_render_settings.shadow_cascades;
        if (s_render_settings.shadow_distance > 0.0f) c.shadow_distance = s_render_settings.shadow_distance;
    }
    /* Two-pass GPU-query occlusion culling (M5): the renderer drives begin_frame
     * / entity_visible / submit_query internally from this pointer.  NULL (when
     * disabled / unsupported) keeps the old always-visible behaviour. */
    c.occlusion_culler = s_occlusion_culler;
    return c;
}

static void app_draw(const JceServices *svc, void *ud)
{
    (void)ud;
    if (!svc || !svc->renderer || !s_scene_renderer || !s_scene || !s_camera)
        return;

    /* Scene render (Top 1 — shipped postfx parity with the editor game view).
     * When the scene authors any post-processing effect, render into an
     * offscreen HDR target and run the engine's OWN postfx pipeline (the same
     * one jce_scene_renderer_render configures from JceSceneRenderingSettings),
     * then present to the backbuffer.  Otherwise — the common case — keep the
     * zero-overhead direct-to-backbuffer path.  Any failure in the postfx path
     * falls through to the direct path so the window is never black. */
    bool present_done = false;
    uint32_t sw = 0, sh = 0;
    if (svc->window) jce_window_get_size(svc->window, &sw, &sh);
    JcePostFXPipeline *pfx = jce_scene_renderer_get_postfx(s_scene_renderer);
    /* NOTE(WebGL2): this bridge briefly had a GLES skip because the whole 3D
     * scene came out black on web.  The ACTUAL root causes were dangling
     * non-2D samplers that WebGL2 rejects draws over — the IBL samplerCUBEs
     * (fixed with sr->dummy_cube) and fs_composite's SAMPLER3D LUT (fixed
     * with dummy_lut3d in jce_postfx.c).  With every sampler parked, the
     * full offscreen-HDR + ACES + bloom chain runs on WebGL2 too, keeping
     * web colors identical to desktop. */
    /* JCE_NO_POSTFX: perf-bisect kill switch — skip the offscreen-HDR bridge
     * entirely and render direct-to-backbuffer LDR (the scene renderer's
     * STOMP honours the same env so shaders take the in-shader-gamma path). */
    static int s_no_postfx = -1;
    if (s_no_postfx < 0)
        s_no_postfx = (getenv("JCE_NO_POSTFX") != NULL) ? 1 : 0;
    if (!s_no_postfx && pfx && sw > 0 && sh > 0) {
        if (!s_post_target) {
            s_post_target = jce_offscreen_target_create(svc->renderer,
                                                        JCE_VIEW_RUNTIME_GAME);
            /* Re-base the post views high so present (base+20, Stage-1a.5
             * worst case with 6-mip bloom pyramid) never collides with the
             * offscreen target's shadow/fog sub-views (30..46).  100+20=120
             * stays well below ImGui (250).  Safe in shipped exe: no editor
             * preview/pick shares the pipeline. */
            if (s_post_target) jce_postfx_set_view_base(pfx, 100);
        }
        if (s_post_target) {
            /* LOW-tier floor (engine guarantee): on iGPU-class hardware
             * (GPU tier LOW — includes every WebGL2 browser, where ANGLE
             * masks the adapter) render the 3D offscreen chain at 0.65x and
             * let the present quad upsample.  Pixel cost drops ~58% while the
             * ECS-UI, drawn directly to the backbuffer, stays at NATIVE
             * resolution (crisp text).  Part of the "hold 60 on integrated
             * graphics" bundle with the grass/bloom/cascade floors — single
             * knobs measured too small alone on a 50ms iGPU frame; the
             * bundle is what moves it.  HIGH/ULTRA render 1:1 as before. */
            uint32_t rw = sw, rh = sh;
            /* Dynamic resolution applies to the fill-bound low-end: the LOW
             * charter baseline AND every INTEGRATED GPU (capped at MEDIUM).  An
             * iGPU's color pass is pixel-count-bound at native res, so the same
             * pixel-budget scaling that holds 60 on the charter box holds it on
             * an iGPU — while UI/text stay native.  Discrete MEDIUM+ renders 1:1. */
            const bool dynres_tier =
                jce_renderer_get_tier() <= JCE_GPU_TIER_LOW ||
                (jce_renderer_get_tier() == JCE_GPU_TIER_MEDIUM &&
                 !jce_renderer_get_recommendation().has_discrete_gpu);
            if (dynres_tier) {
                /* Pixel-BUDGET dynamic resolution (replaces the old flat 0.65x,
                 * which blurred even small windows).  The 3D offscreen chain
                 * renders 1:1 — fully crisp — as long as the surface is within
                 * a pixel budget, and only a large/fullscreen surface scales
                 * down (by area) to hold framerate on iGPU / WebGL.  So the
                 * default window stays sharp while fullscreen still gets relief.
                 * JCE_DYNRES_BUDGET (megapixels) overrides the default. */
                uint64_t budget = 1600000ull;   /* ~1.6 Mpx (≈1440x1111) */
                {
                    const char *b = getenv("JCE_DYNRES_BUDGET");
                    if (b && b[0]) {
                        double mpx = atof(b);
                        if (mpx > 0.05) budget = (uint64_t)(mpx * 1000000.0);
                    }
                }
                uint64_t px = (uint64_t)sw * (uint64_t)sh;
                if (px > budget) {
                    float s = sqrtf((float)budget / (float)px);
                    rw = (uint32_t)((float)sw * s);  if (rw < 16u) rw = sw;
                    rh = (uint32_t)((float)sh * s);  if (rh < 16u) rh = sh;
                }
            }
            float aspect = (float)sw / (float)sh;
            jce_mat4 view = jce_camera_view(s_camera);
            jce_mat4 proj = jce_camera_proj(s_camera, aspect,
                                            jce_gfx_caps().homogeneous_depth);
            /* HDR target: force tone mapping so the PBR linear output maps to
             * display range (else washed out).  No-op on the RGBA8 fallback. */
            if (jce_offscreen_target_prepare(s_post_target, rw, rh,
                                             view.raw[0], proj.raw[0],
                                             0x000000FFu, "RuntimeScene")) {
                JceSceneRenderConfig pcfg = s_default_scene_cfg();
                uint16_t base = jce_offscreen_target_get_view_id(s_post_target);
                /* Postfx path renders into the offscreen target — bind the
                 * occlusion proxy view to its FBO so the proxy depth test reads
                 * the depth the color pass wrote (not the backbuffer → would
                 * make occlusion inert or false-cull visible geometry).  The
                 * no-postfx path below keeps the default UINT16_MAX (backbuffer),
                 * which is exactly where it draws. */
                pcfg.scene_frame_buffer =
                    jce_offscreen_target_get_frame_buffer(s_post_target);
                pcfg.viewport_width  = rw;
                pcfg.viewport_height = rh;
                /* SSR reflects the lit colour RT (gated on the scene's
                 * ssr_enabled); GI L1's dynamic probe gather samples the
                 * same RT, read on the pre-color compute view = last
                 * frame's content.  Both handles must be set: the renderer
                 * treats UINT16_MAX as "no source" and silently skips the
                 * pass, which is why a shipped game could not run SSR at
                 * all while the editor viewport could.  Mirrors
                 * editor/src/scene/jce_editor_viewport_common.h. */
                pcfg.ssr_color_tex_handle =
                    jce_offscreen_target_get_color_texture(s_post_target);
                pcfg.gi_color_tex_handle = pcfg.ssr_color_tex_handle;

                /* Volumetric fog.  Same class of bug SSR had immediately above
                 * and the same fix: the params were mapped in an EDITOR panel,
                 * so a shipped game could not produce them, fog_enabled stayed
                 * false, and the raymarch never executed in a shipped exe at
                 * all.  The mapping now lives in the engine
                 * (jce_scene_fog_params_from_scene) and both consumers call it.
                 *
                 * fog_rt_* must be non-zero or the renderer skips the pass, and
                 * the depth handle must be the one matching THIS frame's
                 * view+proj -- the offscreen target's, not the backbuffer's. */
                /* This main DOES composite (a few lines below), so the
                 * analytic aerial fog must stand down or the frame gets both. */
                pcfg.composites_volumetric_fog = true;
                pcfg.fog_enabled =
                    jce_scene_fog_params_from_scene(s_scene, &pcfg.fog);
                if (pcfg.fog_enabled) {
                    pcfg.scene_depth_tex_handle =
                        jce_offscreen_target_get_depth_texture(s_post_target);
                    pcfg.fog_rt_width  = (int)rw;
                    pcfg.fog_rt_height = (int)rh;
                }

                jce_scene_renderer_render(s_scene_renderer, s_scene, s_camera,
                                          base, s_last_dt, &pcfg);

                /* Composite the fog into the scene RT.  view_base+16 matches
                 * the editor's slot and MUST be greater than the fog render
                 * view (base+15): bgfx executes views in ascending order, so a
                 * lower id would composite last frame's fog. */
                if (pcfg.fog_enabled)
                    jce_scene_renderer_composite_fog(
                        s_scene_renderer, (uint16_t)(base + 16),
                        pcfg.scene_frame_buffer);
                jce_scene_renderer_composite_ssr(
                    s_scene_renderer, (uint16_t)(base + 19),
                    pcfg.scene_frame_buffer);

                JceTextureHandle color = {
                    jce_offscreen_target_get_color_texture(s_post_target) };
                JceTextureHandle depth = {
                    jce_offscreen_target_get_depth_texture(s_post_target) };
                const bool has_fullscreen =
                    jce_scene_renderer_has_fullscreen_effect(s_scene);
                if (has_fullscreen && jce_gfx_texture_valid(color)) {
                    color = jce_scene_renderer_apply_fullscreen_effects(
                        s_scene_renderer, s_scene, s_camera, color, depth,
                        rw, rh, 50, 0,
                        JCE_FULLSCREEN_EFFECT_HDR_BEFORE_POSTFX,
                        s_last_dt);
                }
                /* The "HDR target => force tone mapping" guard used to sit here.  It is
                 * gone on purpose, and NOT because it was in the wrong place.
                 *
                 * 2e5174e3 moved it after jce_scene_renderer_render so the
                 * renderer's per-frame rewrite of scene_rendering->postfx_enabled[]
                 * could no longer stomp it.  That made it live -- and live, it
                 * overrides what a scene explicitly authored.  Its own rationale
                 * was that an untonemapped HDR target reads washed out; bisected
                 * against real content, forcing it ON is what washes out:
                 *
                 *   caged_kingdom/graveyard, same camera, PNG size as a proxy
                 *     ec933eb8 (guard dead)  1,126,840 -> correct
                 *     2e5174e3 (guard live)  1,494,787 -> washed out
                 *
                 * and the split across projects is exactly postfx.tonemap:
                 * elemental_serenity and space author it TRUE (forcing it is a
                 * no-op there, and they always looked right), while caged_kingdom
                 * and street_demo author it FALSE and had their exposure and
                 * lights tuned that way.  A new scene defaults to false, which is
                 * why every newly created scene came up white too.
                 *
                 * Silently overriding an explicit authored value to protect
                 * against a hypothetical is the wrong trade: honour the scene.  A
                 * scene that wants tone mapping says so. */
                bool any_effect = false;
                for (int i = 0; i < JCE_POSTFX_COUNT; ++i)
                    if (jce_postfx_is_enabled(pfx, (JcePostFXType)i)) {
                        any_effect = true; break;
                    }
                if (any_effect || has_fullscreen) {
                    jce_postfx_resize(pfx, rw, rh);
                    if (jce_gfx_texture_valid(color)) {
                        jce_postfx_apply(pfx, color, depth);
                        if (jce_gfx_texture_valid(jce_postfx_get_output(pfx))) {
                            jce_postfx_present(pfx, sw, sh);
                            present_done = true;
                        }
                    }
                }
            }
        }
    }
    if (!present_done) {
        jce_renderer_begin_frame_3d(svc->renderer, svc->window,
                                    s_camera, JCE_VIEW_MAIN_3D);
        JceSceneRenderConfig cfg = s_default_scene_cfg();
        /* Direct-to-backbuffer: scene_frame_buffer stays UINT16_MAX (backbuffer),
         * which is exactly where the color pass draws — the occlusion proxy view
         * binds to the same backbuffer.  Give it the window rect so the proxy
         * raster matches. */
        if (sw > 0 && sh > 0) { cfg.viewport_width = sw; cfg.viewport_height = sh; }
        jce_scene_renderer_render(s_scene_renderer, s_scene, s_camera,
                                  JCE_VIEW_MAIN_3D, s_last_dt, &cfg);
    }

    /* ECS-UI overlay on top of the 3D scene, into the backbuffer on the
     * dedicated UI view (FEATURE 4.1).  While the cursor is captured for
     * FPS-look the OS pointer is pinned/hidden, so authored UI is purely
     * presentational (HUD / labels / backgrounds) and we feed NULL.  When the
     * player frees the cursor (Tab → !s_cursor_captured) we build a real
     * JceUIPointer from the input system — exactly like the editor Game View's
     * pointer (jce_panel_game_view.cpp) — so authored UIButtons hover / press /
     * click.  A click is then drained from the canvas and dispatched to the
     * gameplay script VM through the runtime, making shipped in-game buttons
     * actually do something. */
    if (s_ui_canvas && svc->window) {
        uint32_t sw = 0, sh = 0;
        jce_window_get_size(svc->window, &sw, &sh);
        if (sw > 0 && sh > 0) {
            JceUIPointer ptr;
            const JceUIPointer *ptr_arg = NULL;
            /* Feed the pointer whenever the OS cursor is actually visible:
             * uncaptured, or temporarily released by the hold-ALT preset. */
            if ((!s_cursor_captured || s_preset_alt_active) && svc->input) {
                float mx = 0.0f, my = 0.0f;
                jce_input_mouse_pos(svc->input, &mx, &my);
                ptr.x     = mx;
                ptr.y     = my;
                ptr.down  = jce_input_mouse_button(svc->input,
                                                   JCE_MOUSE_BUTTON_LEFT);
                ptr.valid = true;
                ptr_arg   = &ptr;
            }
            /* ── InputField text/edit channel (single-line text entry) ──
             * Forward editing keys to the focused ECS-UI InputField using the
             * polling input API (these scancodes are pollable), then toggle OS
             * text input as focus changes.  We feed keys BEFORE the render so
             * they apply to the focus established last frame, and the render
             * below re-evaluates focus from this frame's pointer.
             *
             * NOTE: the polling JceInput API exposes no UTF-8 character stream
             * (only key state), so the *character* channel below is a clearly
             * marked hook: when this drop-in main is replaced with a project
             * main.c that registers a JceAppDesc.on_event callback, route
             *   JCE_EVENT_TEXT_INPUT  → jce_ui_canvas_text_input(s_ui_canvas, ev.text.text)
             *   JCE_EVENT_KEY_DOWN     → jce_ui_canvas_key_edit(s_ui_canvas, ev.key.scancode, ev.key.mod)
             *   JCE_EVENT_MOUSE_WHEEL  → jce_ui_canvas_scroll(s_ui_canvas, ev.wheel.x, ev.wheel.y)
             * (the reference wiring).  Starting OS text input here means SDL is
             * already emitting those text events for that future callback.
             * See deviations/followups. */
            if (svc->input && jce_ui_canvas_focused_input(s_ui_canvas)) {
                static const struct { int key; } s_edit_keys[] = {
                    { JCE_KEY_BACKSPACE }, { JCE_KEY_DELETE },
                    { JCE_KEY_LEFT }, { JCE_KEY_RIGHT },
                    { JCE_KEY_HOME }, { JCE_KEY_END },
                    { JCE_KEY_RETURN }, { JCE_KEY_KP_ENTER },
                    { JCE_KEY_ESCAPE },
                };
                for (size_t i = 0; i < sizeof(s_edit_keys)/sizeof(s_edit_keys[0]); ++i)
                    if (jce_input_key_pressed(svc->input, s_edit_keys[i].key))
                        jce_ui_canvas_key_edit(s_ui_canvas, s_edit_keys[i].key, 0);
            }

            jce_ui_canvas_render(s_ui_canvas, s_scene, JCE_VIEW_UI, UINT16_MAX,
                                 (float)sw, (float)sh, ptr_arg, s_last_dt);

            /* ── ScrollView wheel channel ──────────────────────────────
             * Feed the (vertical) mouse wheel to the scroll view under the
             * pointer, AFTER the render so the canvas has resolved this frame's
             * hovered scroll view.  The polling JceInput exposes only a vertical
             * wheel (+y = up), matching jce_ui_canvas_scroll's dy convention; a
             * project main.c with an on_event callback can additionally forward
             * ev.wheel.x for horizontal scrolling (see reference wiring above).
             * Fire-and-forget: a no-op when no scroll view is hovered. */
            if (ptr_arg && svc->input) {
                float wheel = jce_input_mouse_wheel(svc->input);
                if (wheel != 0.0f)
                    jce_ui_canvas_scroll(s_ui_canvas, 0.0f, wheel);
            }

            /* OS text-input follows InputField focus (toggle on the edge so we
             * don't spam the platform layer). */
            {
                static bool s_text_input_on = false;
                bool want = jce_ui_canvas_focused_input(s_ui_canvas) != 0;
                if (want != s_text_input_on) {
                    if (want) jce_window_start_text_input(svc->window);
                    else      jce_window_stop_text_input(svc->window);
                    s_text_input_on = want;
                }
            }

            /* Drain the click the canvas state machine recorded this frame
             * (set only on the release frame, over the same button) and fire
             * the button's authored on_click_handler through the script VM.
             * No-op when nothing was clicked / no handler / no runtime. */
            if (ptr_arg && s_runtime && s_scene) {
                uint64_t clicked = jce_ui_canvas_last_clicked(s_ui_canvas);
                if (clicked) {
                    JceUIButtonComponent *bt =
                        jce_scene_get_ui_button(s_scene, (JceEntity)clicked);
                    if (bt)
                        jce_runtime_dispatch_ui_click(s_runtime, clicked,
                                                      bt->on_click_handler);
                }
                /* Slider drag / toggle flip / dropdown select → on_value_changed;
                 * InputField edits → on_value_changed; RETURN → on_submit.  The
                 * runtime resolves the widget on its own scene and fires the
                 * authored handler; each is a clean no-op when none authored. */
                uint64_t vc = jce_ui_canvas_last_value_changed(s_ui_canvas);
                if (vc) jce_runtime_dispatch_ui_value_changed(s_runtime, vc);
                uint64_t tc = jce_ui_canvas_last_text_changed(s_ui_canvas);
                if (tc) jce_runtime_dispatch_ui_text_changed(s_runtime, tc);
                uint64_t sub = jce_ui_canvas_last_submitted(s_ui_canvas);
                if (sub) jce_runtime_dispatch_ui_submit(s_runtime, sub);
            }
        }
    }

    /* Host-independent QA capture.  Submit only after the scene, post-fx, and
     * UI overlay have all populated this frame's backbuffer.  Completion is
     * observed through the renderer's one-in-flight screenshot contract, so
     * ordered schedules cannot overwrite or reorder files. */
    if (s_kpi_game_shots_active) {
        if (s_kpi_game_shots.in_flight && !jce_screenshot_pending()) {
            jce_screenshot_schedule_mark_complete(&s_kpi_game_shots, true);
            LOG_INFO("app", "%s", "deterministic game capture completed");
        }
        {
            const JceScreenshotScheduleEntry *due =
                jce_screenshot_schedule_due(&s_kpi_game_shots);
            if (due && !jce_screenshot_pending()) {
                if (jce_screenshot_save(due->path, JCE_SCREENSHOT_PNG) &&
                    jce_screenshot_schedule_mark_submitted(
                        &s_kpi_game_shots)) {
                    LOG_INFO("app", "deterministic game capture submitted: %s",
                             due->path);
                } else {
                    (void)jce_screenshot_schedule_mark_submitted(
                        &s_kpi_game_shots);
                    jce_screenshot_schedule_mark_complete(
                        &s_kpi_game_shots, false);
                    LOG_ERROR("app", "deterministic game capture failed: %s",
                              due->path);
                }
            }
        }
    }
}

static void app_exit(void *ud)
{
    (void)ud;
    s_kpi_game_shots_active = false;
    memset(&s_kpi_game_shots, 0, sizeof(s_kpi_game_shots));
    /* Finalize a still-running F9 recording so the container is playable. */
    if (s_preset_rec_active) {
        if (s_svc && s_svc->renderer)
            jce_renderer_set_backbuffer_capture(s_svc->renderer, false);
        jce_renderer_set_capture_sink(NULL, NULL, NULL, NULL);
        if (s_preset_rec) { jce_webm_encoder_finish(s_preset_rec); s_preset_rec = NULL; }
        s_preset_rec_active = false;
    }
    /* Streamer first: it removes streamed entities and joins its private
     * structured executor before the scene or filesystem are destroyed. */
    if (s_world_streamer) { jce_world_streamer_destroy(s_world_streamer);  s_world_streamer = NULL; }
    if (s_runtime)        { jce_runtime_destroy(s_runtime);              s_runtime        = NULL; }
    if (s_ui_canvas)      { jce_ui_canvas_destroy(s_ui_canvas);          s_ui_canvas      = NULL; }
    /* Occlusion culler holds bgfx resources (proxy geom + query handles) —
     * destroy before the renderer/bgfx shut down. */
    if (s_occlusion_culler) { jce_occlusion_culler_destroy(s_occlusion_culler); s_occlusion_culler = NULL; }
    /* Offscreen postfx target borrows the renderer — destroy before it. */
    if (s_post_target)    { jce_offscreen_target_destroy(s_post_target);  s_post_target    = NULL; }
    if (s_scene_renderer) { jce_scene_renderer_destroy(s_scene_renderer); s_scene_renderer = NULL; }
    /* Destroy cached meshes (owned here) before tearing the rest down, then
     * free the growable cache + its hash index. */
    for (uint32_t i = 0; i < s_mesh_cache_count; ++i) {
        if (s_mesh_cache[i].mesh) jce_mesh_destroy(s_mesh_cache[i].mesh);
        free(s_mesh_cache[i].path);
    }
    free(s_mesh_cache);  s_mesh_cache = NULL;
    free(s_mesh_index);  s_mesh_index = NULL;
    s_mesh_cache_count = 0; s_mesh_cache_cap = 0; s_mesh_index_cap = 0;
    if (s_camera)         { jce_camera_destroy(s_camera);                 s_camera         = NULL; }
    if (s_scene)          { jce_scene_destroy(s_scene);                   s_scene          = NULL; }
    if (s_runtime_fs) {
        if (jce_fs_get_active() == s_runtime_fs)
            jce_fs_set_active(NULL);
        jce_fs_destroy(s_runtime_fs);
        s_runtime_fs = NULL;
    }
    jce_default_unmount_project_bundles();
    if (s_project)        { jce_project_free(s_project);                  s_project        = NULL; }
    s_svc = NULL;
}

#endif /* JCE_DEFAULT_MAIN_INC_H */
